```java
// Vulnerable code: SQL Injection due to concatenated user input
public boolean authenticateUser(String username, String password, Connection conn) throws SQLException {
    String query = "SELECT * FROM users WHERE username = '" + username + "' AND password = '" + password + "'";
    Statement stmt = conn.createStatement();
    ResultSet rs = stmt.executeQuery(query);
    return rs.next(); // Returns true if any matching user exists
}
```

***
```java
// Secure code: Uses PreparedStatement to prevent SQL Injection
public boolean authenticateUser(String username, String password, Connection conn) throws SQLException {
    String query = "SELECT * FROM users WHERE username = ? AND password = ?";
    PreparedStatement stmt = conn.prepareStatement(query);
    stmt.setString(1, username); // Parameterized queries
    stmt.setString(2, password);
    ResultSet rs = stmt.executeQuery();
    return rs.next(); // Returns true if valid credentials
}
```

